function Page_IllustratedHandbookCupView:OnInitScrollView()
    local DataTable = IllustratedHandbookDataManager:Get():GetIllustratedHandbookDataList(IllustratedHandbookType.Cup)
    CommonHelper:InitMoreRowScrollView(self.MoreRowScrollView_V, #DataTable, 4, function(index, item, scrollview)
        CommonHelper:SetGameObjectActive("UnActiveBg", item, not DataTable[index + 1]:IsActive())
        CommonHelper:SetGameObjectActive("ActiveBg", item, DataTable[index + 1]:IsActive())

        CommonHelper:SetText("UnActiveBg/###name", item, CommonHelper:GetTempStr_Default(DataTable[index + 1]:GetCupCollectConfig().name))
        CommonHelper:SetText("ActiveBg/###name", item, CommonHelper:GetTempStr_Default(DataTable[index + 1]:GetCupCollectConfig().name))
        ---@type dictarticle_config_cell
        local articleCfg = CommonHelper:GetTableDataByID(ConfigNames.article_config, DataTable[index + 1].cupid)
        --CommonHelper:GetComponentSetUITexture("UnActiveBg/icon",item,DataTable[index+1]:GetCupCollectConfig().icon,self:GetUIModuleID())
        --CommonHelper:GetComponentSetUITexture("ActiveBg/icon",item,DataTable[index+1]:GetCupCollectConfig().icon,self:GetUIModuleID())
        if articleCfg then
            CommonHelper:GetComponentSetUITexture("UnActiveBg/icon", item, articleCfg.icon .. ".png", self:GetUIModuleID())
            CommonHelper:GetComponentSetUITexture("ActiveBg/icon", item, articleCfg.icon .. ".png", self:GetUIModuleID())
        end

        CommonHelper:HButtonSetCallback("UnActiveBg/BtnDetail", item, function()
            CommonHelper:ShowHelpView(DataTable[index + 1]:GetCupCollectConfig().detail,DataTable[index + 1]:GetCupCollectConfig().name,nil,true)
        end)
        CommonHelper:HButtonSetCallback("ActiveBg/BtnDetail", item, function()
            CommonHelper:ShowHelpView(DataTable[index + 1]:GetCupCollectConfig().detail,DataTable[index + 1]:GetCupCollectConfig().name,nil,true)
        end)
        CommonHelper:SetGameObjectActive("ActiveBg/BtnCupGet", item, DataTable[index + 1].giftflag == 0)
        CommonHelper:HButtonSetCallback("ActiveBg/BtnCupGet", item, function()
            IllustratedHandbookSubsystem:Get():SendMsg_CupCollectGift(DataTable[index + 1].cupid)
        end)

    end)
end

